import {VILLAGES} from './settlements.js';
export function drawSettlement(view,c,s,n){if(n.type!=='settlement')return false;const d=VILLAGES[n.village],v=s.settlements.villages[n.village];c.save();c.translate(n.x,n.y);c.fillStyle='#48624d77';c.beginPath();c.ellipse(0,0,90,38,0,0,7);c.fill();
 for(let i=0;i<3;i++){const x=(i-1)*57,y=i===1?-15:0;c.fillStyle='#8d8060';c.fillRect(x-24,y-49,48,40);c.fillStyle=d.color;c.strokeStyle='#344c3f';c.lineWidth=3;c.beginPath();c.moveTo(x-33,y-46);c.lineTo(x,y-83);c.lineTo(x+33,y-46);c.closePath();c.fill();c.stroke();c.fillStyle='#354b3d';c.fillRect(x-8,y-33,16,24);}
 for(let i=0;i<v.population-1;i++){const a=i*2.399,x=Math.cos(a)*(34+i*4),y=12+Math.sin(a)*18+(view.reducedMotion?0:Math.sin(s.time*1.5+i)*2);c.fillStyle=i%2?d.color:'#829b83';c.beginPath();c.moveTo(x,y-27);c.lineTo(x-6,y-8);c.lineTo(x+6,y-8);c.closePath();c.fill();c.fillStyle='#dec59c';c.beginPath();c.arc(x,y-30,4,0,7);c.fill();}
 c.restore();view.sprite(c,'companion-keeper',n.x+38,n.y+18+(view.reducedMotion?0:Math.sin(s.time*2)*.7),68);c.font='bold 12px sans-serif';c.textAlign='center';c.lineWidth=4;c.strokeStyle='#243c32';const text=d.name+' · '+v.population+' 人'+(s.level<d.level?' · '+d.level+'级开放':'');c.strokeText(text,n.x,n.y-110);c.fillStyle=d.color;c.fillText(text,n.x,n.y-110);return true;}
